12	/**
13	 * @param {(string | RegExp)[] | undefined} origins
14	 * @param {string} name
15	 */
16	function assertCacheOrigins (origins, name) {
17	  if (origins === undefined) return
18	  if (!Array.isArray(origins)) {
19	    throw new TypeError(`expected ${name} to be an array or undefined, got ${typeof origins}`)
20	  }
21	  for (let i = 0; i < origins.length; i++) {
22	    const origin = origins[i]
23	    if (typeof origin !== 'string' && !(origin instanceof RegExp)) {
24	      throw new TypeError(`expected ${name}[${i}] to be a string or RegExp, got ${typeof origin}`)
25	    }
26	  }
27	}
28	
29	const nop = () => {}
30	
31	/**
32	 * @typedef {(options: import('../../types/dispatcher.d.ts').default.DispatchOptions, handler: import('../../types/dispatcher.d.ts').default.DispatchHandler) => void} DispatchFn
33	 */
34	
35	/**
36	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
37	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} cacheControlDirectives
38	 * @param {import('../../types/dispatcher.d.ts').default.RequestOptions} opts
39	 * @returns {boolean}
40	 */
41	function needsRevalidation (result, cacheControlDirectives, { headers = {} }) {
42	  // Always revalidate requests with the no-cache request directive.
43	  if (cacheControlDirectives?.['no-cache']) {
44	    return true
45	  }
46	
47	  // Always revalidate requests with unqualified no-cache response directive.
48	  if (result.cacheControlDirectives?.['no-cache'] && !Array.isArray(result.cacheControlDirectives['no-cache'])) {
49	    return true
50	  }
51	
52	  // Always revalidate requests with conditional headers.
53	  if (headers['if-modified-since'] || headers['if-none-match']) {
54	    return true
55	  }
56	
57	  return false
58	}
59	
60	/**
61	 * must-revalidate (proxy-revalidate for shared caches) forbids serving a stale
62	 * response without successful validation, overriding max-stale and stale-if-error.
63	 * https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.2.2
64	 * https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.2.8
65	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
66	 * @param {'shared' | 'private'} cacheType
67	 * @returns {boolean}
68	 */
69	function forbidsServingStale (result, cacheType) {
70	  return Boolean(
71	    result.cacheControlDirectives?.['must-revalidate'] ||
72	    (cacheType === 'shared' && result.cacheControlDirectives?.['proxy-revalidate'])
73	  )
74	}
75	
76	/**
77	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
78	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} cacheControlDirectives
79	 * @param {'shared' | 'private'} cacheType
80	 * @returns {boolean}
81	 */
82	function isStale (result, cacheControlDirectives, cacheType) {
83	  const now = Date.now()
84	  if (now > result.staleAt) {
85	    // Response is stale
86	    if (cacheControlDirectives?.['max-stale'] && !forbidsServingStale(result, cacheType)) {
87	      // There's a threshold where we can serve stale responses, let's see if
88	      //  we're in it
89	      // https://www.rfc-editor.org/rfc/rfc9111.html#name-max-stale
90	      const gracePeriod = result.staleAt + (cacheControlDirectives['max-stale'] * 1000)
91	      return now > gracePeriod
92	    }
93	
94	    return true
95	  }
96	
97	  if (cacheControlDirectives?.['min-fresh']) {
98	    // https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.1.3
99	
100	    // At this point, staleAt is always > now
101	    const timeLeftTillStale = result.staleAt - now
102	    const threshold = cacheControlDirectives['min-fresh'] * 1000
103	
104	    return timeLeftTillStale <= threshold
105	  }
106	
107	  return false
108	}
109	
110	/**
111	 * Check if we're within the stale-while-revalidate window for a stale response
112	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
113	 * @returns {boolean}
114	 */
115	function withinStaleWhileRevalidateWindow (result) {
116	  const staleWhileRevalidate = result.cacheControlDirectives?.['stale-while-revalidate']
117	  if (!staleWhileRevalidate) {
118	    return false
119	  }
120	
121	  const now = Date.now()
122	  const staleWhileRevalidateExpiry = result.staleAt + (staleWhileRevalidate * 1000)
123	  return now <= staleWhileRevalidateExpiry
124	}
125	
126	/**
127	 * @param {DispatchFn} dispatch
128	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheHandlerOptions} globalOpts
129	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheKey} cacheKey
130	 * @param {import('../../types/dispatcher.d.ts').default.DispatchHandler} handler
131	 * @param {import('../../types/dispatcher.d.ts').default.RequestOptions} opts
132	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} reqCacheControl
133	 */
134	function handleUncachedResponse (
135	  dispatch,
136	  globalOpts,
137	  cacheKey,
138	  handler,
139	  opts,
140	  reqCacheControl
141	) {
142	  if (reqCacheControl?.['only-if-cached']) {
143	    let aborted = false
144	
145	    const controller = {
146	      paused: false,
147	      rawHeaders: [],
148	      rawTrailers: [],
149	      pause () {
150	        this.paused = true
151	      },
152	      resume () {
153	        this.paused = false
154	      },
155	      abort: (reason) => {
156	        aborted = true
157	        handler.onResponseError?.(controller, reason ?? new AbortError())
158	      }
159	    }
160	
161	    try {
162	      handler.onRequestStart?.(controller, null)
163	
164	      if (aborted) {
165	        return
166	      }
167	
168	      handler.onResponseStart?.(controller, 504, {}, 'Gateway Timeout')
169	      if (aborted) {
170	        return
171	      }
172	
173	      handler.onResponseEnd?.(controller, {})
174	    } catch (err) {
175	      if (typeof handler.onResponseError === 'function') {
176	        handler.onResponseError(controller, err)
177	      }
178	    }
179	
180	    return true
181	  }
182	
183	  return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
184	}
185	
186	/**
187	 * @param {import('../../types/dispatcher.d.ts').default.DispatchHandler} handler
188	 * @param {import('../../types/dispatcher.d.ts').default.RequestOptions} opts
189	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
190	 * @param {number} age
191	 * @param {any} context
192	 * @param {boolean} isStale
193	 */
194	function sendCachedValue (handler, opts, result, age, context, isStale) {
195	  // TODO (perf): Readable.from path can be optimized...
196	  const stream = util.isStream(result.body)
197	    ? result.body
198	    : Readable.from(result.body ?? [])
199	
200	  assert(!stream.destroyed, 'stream should not be destroyed')
201	  assert(!stream.readableDidRead, 'stream should not be readableDidRead')
202	
203	  const controller = {
204	    rawHeaders: [],
205	    rawTrailers: [],
206	    resume () {
207	      stream.resume()
208	    },
209	    pause () {
210	      stream.pause()
211	    },
212	    get paused () {
213	      return stream.isPaused()
214	    },
215	    get aborted () {
216	      return stream.destroyed
217	    },
218	    get reason () {
219	      return stream.errored
220	    },
221	    abort (reason) {
222	      stream.destroy(reason ?? new AbortError())
223	    }
224	  }
225	
226	  stream
227	    .on('error', function (err) {
228	      if (!this.readableEnded) {
229	        if (typeof handler.onResponseError === 'function') {
230	          handler.onResponseError(controller, err)
231	        } else {
232	          throw err
233	        }
234	      }
235	    })
236	    .on('close', function () {
237	      if (!this.errored) {
238	        handler.onResponseEnd?.(controller, {})
239	      }
240	    })
241	
242	  handler.onRequestStart?.(controller, context)
243	
244	  if (stream.destroyed) {
245	    return
246	  }
247	
248	  // Add the age header
249	  // https://www.rfc-editor.org/rfc/rfc9111.html#name-age
250	  const headers = { ...result.headers, age: String(age) }
251	
252	  if (isStale) {
253	    // Add warning header
254	    //  https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Warning
255	    headers.warning = '110 - "response is stale"'
256	  }
257	
258	  controller.rawHeaders = util.toRawHeaders(headers)
259	
260	  handler.onResponseStart?.(controller, result.statusCode, headers, result.statusMessage)
261	
262	  if (opts.method === 'HEAD') {
263	    stream.destroy()
264	  } else {
265	    stream.on('data', function (chunk) {
266	      handler.onResponseData?.(controller, chunk)
267	    })
268	  }
269	}
270	
271	/**
272	 * @param {DispatchFn} dispatch
273	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheHandlerOptions} globalOpts
274	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheKey} cacheKey
275	 * @param {import('../../types/dispatcher.d.ts').default.DispatchHandler} handler
276	 * @param {import('../../types/dispatcher.d.ts').default.RequestOptions} opts
277	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} reqCacheControl
278	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult | undefined} result
279	 */
280	function handleResult (
281	  dispatch,
282	  globalOpts,
283	  cacheKey,
284	  handler,
285	  opts,
286	  reqCacheControl,
287	  result
288	) {
289	  if (!result) {
290	    return handleUncachedResponse(dispatch, globalOpts, cacheKey, handler, opts, reqCacheControl)
291	  }
292	
293	  const now = Date.now()
294	  if (now > result.deleteAt) {
295	    // Response is expired, cache store shouldn't have given this to us
296	    return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
297	  }
298	
299	  const age = Math.round((now - result.cachedAt) / 1000)
300	  if (reqCacheControl?.['max-age'] && age >= reqCacheControl['max-age']) {
301	    // Response is considered expired for this specific request
302	    //  https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.1.1
303	    return dispatch(opts, handler)
304	  }
305	
306	  const stale = isStale(result, reqCacheControl, globalOpts.type)
307	  const revalidate = needsRevalidation(result, reqCacheControl, opts)
308	
309	  // Check if the response is stale
310	  if (stale || revalidate) {
311	    if (util.isStream(opts.body) && util.bodyLength(opts.body) !== 0) {
312	      // If body is a stream we can't revalidate...
313	      // TODO (fix): This could be less strict...
314	      return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
315	    }
316	
317	    // RFC 5861: If we're within stale-while-revalidate window, serve stale immediately
318	    // and revalidate in background, unless immediate revalidation is necessary
319	    if (!revalidate && withinStaleWhileRevalidateWindow(result)) {
320	      // Serve stale response immediately
321	      sendCachedValue(handler, opts, result, age, null, true)
322	
323	      // Start background revalidation (fire-and-forget)
324	      queueMicrotask(() => {
325	        const headers = {
326	          ...opts.headers,
327	          'if-modified-since': new Date(result.cachedAt).toUTCString()
328	        }
329	
330	        if (result.etag) {
331	          headers['if-none-match'] = result.etag
332	        }
333	
334	        if (result.vary) {
335	          for (const key in result.vary) {
336	            if (result.vary[key] != null) {
337	              headers[key] = result.vary[key]
338	            }
339	          }
340	        }
341	
342	        // Background revalidation - update cache if we get new data
343	        dispatch(
344	          {
345	            ...opts,
346	            headers
347	          },
348	          new CacheHandler(globalOpts, cacheKey, {
349	            // Silent handler that just updates the cache
350	            onRequestStart () {},
351	            onRequestUpgrade () {},
352	            onResponseStart () {},
353	            onResponseData () {},
354	            onResponseEnd () {},
355	            onResponseError () {}
356	          })
357	        )
358	      })
359	
360	      return true
361	    }
362	
363	    let withinStaleIfErrorThreshold = false
364	    const staleIfErrorExpiry = result.cacheControlDirectives['stale-if-error'] ?? reqCacheControl?.['stale-if-error']
365	    if (staleIfErrorExpiry && !forbidsServingStale(result, globalOpts.type)) {
366	      withinStaleIfErrorThreshold = now < (result.staleAt + (staleIfErrorExpiry * 1000))
367	    }
368	
369	    const headers = {
370	      ...opts.headers,
371	      'if-modified-since': new Date(result.cachedAt).toUTCString()
372	    }
373	
374	    if (result.etag) {
375	      headers['if-none-match'] = result.etag
376	    }
377	
378	    if (result.vary) {
379	      for (const key in result.vary) {
380	        if (result.vary[key] != null) {
381	          headers[key] = result.vary[key]
382	        }
383	      }
384	    }
385	
386	    // We need to revalidate the response
387	    return dispatch(
388	      {
389	        ...opts,
390	        headers
391	      },
392	      new CacheRevalidationHandler(
393	        (success, context) => {
394	          if (success) {
395	            // TODO: successful revalidation should be considered fresh (not give stale warning).
396	            sendCachedValue(handler, opts, result, age, context, stale)
397	          } else if (util.isStream(result.body)) {
398	            result.body.on('error', nop).destroy()
399	          }
400	        },
401	        new CacheHandler(globalOpts, cacheKey, handler),
402	        withinStaleIfErrorThreshold
403	      )
404	    )
405	  }
406	
407	  // Dump request body.
408	  if (util.isStream(opts.body)) {
409	    opts.body.on('error', nop).destroy()
410	  }
411	
412	  sendCachedValue(handler, opts, result, age, null, false)
413	}
414	
415	/**
416	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheOptions} [opts]
417	 * @returns {import('../../types/dispatcher.d.ts').default.DispatcherComposeInterceptor}
418	 */
419	module.exports = (opts = {}) => {
420	  const {
421	    store = new MemoryCacheStore(),
422	    methods = ['GET'],
423	    cacheByDefault = undefined,
424	    type = 'shared',
425	    origins = undefined
426	  } = opts
427	
428	  if (typeof opts !== 'object' || opts === null) {
429	    throw new TypeError(`expected type of opts to be an Object, got ${opts === null ? 'null' : typeof opts}`)
430	  }
431	
432	  assertCacheStore(store, 'opts.store')
433	  assertCacheMethods(methods, 'opts.methods')
434	  assertCacheOrigins(origins, 'opts.origins')
435	
436	  if (typeof cacheByDefault !== 'undefined' && typeof cacheByDefault !== 'number') {
437	    throw new TypeError(`expected opts.cacheByDefault to be number or undefined, got ${typeof cacheByDefault}`)
438	  }
439	
440	  if (typeof type !== 'undefined' && type !== 'shared' && type !== 'private') {
441	    throw new TypeError(`expected opts.type to be shared, private, or undefined, got ${typeof type}`)
442	  }
443	
444	  const globalOpts = {
445	    store,
446	    methods,
447	    cacheByDefault,
448	    type
449	  }
450	
451	  const safeMethodsToNotCache = util.safeHTTPMethods.filter(method => methods.includes(method) === false)
452	
453	  return dispatch => {
454	    return (opts, handler) => {
455	      if (!opts.origin || safeMethodsToNotCache.includes(opts.method)) {
456	        // Not a method we want to cache or we don't have the origin, skip
457	        return dispatch(opts, handler)
458	      }
459	
460	      // Check if origin is in whitelist
461	      if (origins !== undefined) {
462	        const requestOrigin = opts.origin.toString().toLowerCase()
463	        let isAllowed = false
464	
465	        for (let i = 0; i < origins.length; i++) {
466	          const allowed = origins[i]
467	          if (typeof allowed === 'string') {
468	            if (allowed.toLowerCase() === requestOrigin) {
469	              isAllowed = true
470	              break
471	            }
472	          } else if (allowed.test(requestOrigin)) {
473	            isAllowed = true
474	            break
475	          }
476	        }
477	
478	        if (!isAllowed) {
479	          return dispatch(opts, handler)
480	        }
481	      }
482	
483	      opts = {
484	        ...opts,
485	        headers: normalizeHeaders(opts)
486	      }
487	
488	      const reqCacheControl = opts.headers?.['cache-control']
489	        ? parseCacheControlHeader(opts.headers['cache-control'])
490	        : undefined
491	
492	      if (reqCacheControl?.['no-store']) {
493	        return dispatch(opts, handler)
494	      }
495	
496	      /**
497	       * @type {import('../../types/cache-interceptor.d.ts').default.CacheKey}
498	       */
499	      const cacheKey = makeCacheKey(opts)
500	      const result = store.get(cacheKey)
501	
502	      if (result && typeof result.then === 'function') {
503	        return result
504	          .then(result => handleResult(dispatch,
505	            globalOpts,
506	            cacheKey,
507	            handler,
508	            opts,
509	            reqCacheControl,
510	            result
511	          ))
512	      } else {
513	        return handleResult(
514	          dispatch,
515	          globalOpts,
516	          cacheKey,
517	          handler,
518	          opts,
519	          reqCacheControl,
520	          result
521	        )
522	      }
523	    }
524	  }
525	}
