          if (req.headers['if-none-match'] !== '"asd123"') {
            res.statusCode = 500
            res.end('received incorrect etag')
            return
          }

          res.statusCode = 304
          res.end()
        } else {
          requestsToOrigin++
          res.setHeader('cache-control', 'public, s-maxage=1, must-revalidate')
          res.setHeader('etag', '"asd123"')
          res.end('asd')
