  test('unsafe methods purge the location & content-location uris from cache', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      if (req.method === 'GET') {
        requestsToOrigin++
        res.setHeader('cache-control', 's-maxage=10')
        res.end('asd')
        return
      }

      // The unsafe request tells us which fields to respond with
      const { searchParams } = new URL(req.url, 'http://localhost')
      for (const header of ['location', 'content-location']) {
        const value = searchParams.get(header)
        if (value !== null) {
          res.setHeader(header, value)
        }
      }

      res.statusCode = 201
      res.end('')
    }).listen(0)

    after(() => server.close())
    await once(server, 'listening')

    const origin = `http://localhost:${server.address().port}`
    const client = new Client(origin)
      .compose(interceptors.cache({ store: new MemoryCacheStore() }))

    after(async () => { await client.close() })

    const cacheTarget = async () => {
      await (await client.request({ origin, method: 'GET', path: '/target' })).body.dump()
    }

    // Sanity check, the second request is served from the cache
    await cacheTarget()
    await cacheTarget()
    equal(requestsToOrigin, 1)

    for (const query of [
      'location=/target',
      `location=${origin}/target`,
      'content-location=/target',
      // Both fields at once, the target should only be refetched once
      `location=/target&content-location=${origin}/target`
    ]) {
      const requestsBefore = requestsToOrigin

      await (await client.request({
        origin,
        method: 'POST',
        path: `/src?${query}`
      })).body.dump()

      await cacheTarget()
      equal(requestsToOrigin, requestsBefore + 1, query)

      // And it's cached again
      await cacheTarget()
      equal(requestsToOrigin, requestsBefore + 1, query)
    }

    // Cross-origin uris aren't invalidated
    const requestsBefore = requestsToOrigin
    for (const query of [
      'location=http://example.com/target',
      'content-location=https://localhost/target',
      'location=//example.com/target'
    ]) {
      await (await client.request({
        origin,
        method: 'POST',
        path: `/src?${encodeURI(query)}`
      })).body.dump()

      await cacheTarget()
      equal(requestsToOrigin, requestsBefore, query)
    }
  })

