+/**
+ * Resolves the response's Location and Content-Location fields against the
+ *  request's URI, keeping the ones that share its origin.
+ * @see https://www.rfc-editor.org/rfc/rfc9111.html#section-4.4
+ *
+ * @param {import('../../types/cache-interceptor.d.ts').default.CacheKey} cacheKey
+ * @param {import('../../types/header.d.ts').IncomingHttpHeaders} resHeaders
+ * @returns {string[]} the paths (query included) to invalidate
+ */
+function getSameOriginInvalidationPaths (cacheKey, resHeaders) {
+  const location = resHeaders.location
+  const contentLocation = resHeaders['content-location']
+  if (typeof location !== 'string' && typeof contentLocation !== 'string') {
+    return []
+  }
+
+  let requestUri
+  try {
+    requestUri = new URL(
+      cacheKey.path,
+      URL.canParse(cacheKey.origin) ? cacheKey.origin : UNPARSABLE_ORIGIN_BASE
+    )
+  } catch {
+    return []
+  }
+
+  const paths = []
+  for (const value of [location, contentLocation]) {
+    if (typeof value !== 'string' || value.length === 0) {
+      continue
+    }
+
+    let uri
+    try {
+      uri = new URL(value, requestUri)
+    } catch {
+      // Not a valid URI reference, nothing to invalidate
+      continue
+    }
+
+    if (uri.protocol !== requestUri.protocol || uri.host !== requestUri.host) {
+      // Different origin, the response isn't authoritative for it
+      continue
+    }
+
+    const path = `${uri.pathname}${uri.search}`
+    if (path !== cacheKey.path && !paths.includes(path)) {
+      paths.push(path)
+    }
+  }
+
+  return paths
 }

